// 64-bit integers converted to f32: the Apple Paravirtual device read the folded first one as about 2^71.
// words: float float float float float float
// input: u32
// output: u32
// overflow checks: off
#![cfg_attr(not(cpu_reference), no_std)]
#![allow(unused_mut, unused_variables, unused_assignments, unused_parens, unused_labels, unused_braces, unused_comparisons, unused_imports, dead_code, unreachable_code, arithmetic_overflow, unconditional_panic)]

fn run(input: u32) -> [u32; 6] {
    let all = !(0_u64.reverse_bits());
    let varying = ((input as u64) << 32) | (input as u64);
    let tie = (1_u64 << 40) | (1_u64 << 16) | (input as u64 & 1);
    let negative = ((input as isize) << 31) - (1_isize << 62);
    [
        (all as f32).to_bits(),
        (varying as f32).to_bits(),
        (tie as f32).to_bits(),
        ((varying as usize) as f32).to_bits(),
        (negative as f32).to_bits(),
        ((u64::MAX - (input as u64)) as f32).to_bits(),
    ]
}

#[cfg(not(cpu_reference))]
use metal_oxide_device::{ReadBuffer, WriteBuffer, block_dim, block_idx, kernel, thread_idx};

#[cfg(not(cpu_reference))]
#[kernel]
pub unsafe fn generated(input: ReadBuffer<u32>, output: WriteBuffer<u32>, n: u32) {
    let i = block_idx().x * block_dim().x + thread_idx().x;
    if i < n {
        let words = run(unsafe { input.load_unchecked(i) });
        unsafe {
        output.store_unchecked(i * 6 + 0, words[0]);
        output.store_unchecked(i * 6 + 1, words[1]);
        output.store_unchecked(i * 6 + 2, words[2]);
        output.store_unchecked(i * 6 + 3, words[3]);
        output.store_unchecked(i * 6 + 4, words[4]);
        output.store_unchecked(i * 6 + 5, words[5]);
        }
    }
}

